  t("<b>Mughal courts in Bengal (before 1772)</b>", "<b>Two ladders:</b> civil and criminal", "<b>Civil (Diwani = finance, LR, civil justice):</b> local up to <b>Sadar Diwani Adalat (SDA)</b> at suba; personal laws of Hindus + Muslims for marriage, inheritance; <b>Pandits</b> judged Hindu cases, <b>Maulvis</b> Muslim; <b>Diwan = Chief Justice of SDA</b>; LR + non-personal disputes: original jurisdiction <b>Zamindar</b> in his <b>Kachari</b>; appeals Zamindar > <b>Amil</b> (district revenue officer) > SDA at <b>Murshidabad</b> (Diwan / Naib Diwan)", "<b>Criminal:</b> <b>Nizamat (Faujdari) Adalats</b> at district, <b>Sadar Nizamat Adalat (SNA)</b> on top headed by <b>Naib Nazim</b>; Islamic state: <b>Islamic law for all</b>; village Zamindar = petty crimes + police duty; major crimes straight to district court", "<b>Division of labour:</b> <b>Kazi</b> = judge ('2 People Bench' Kazi with Mufti), <b>Mufti</b> = expert on Islamic law, <b>Faujdar</b> (executive police chief, like today's SP) secures accused + <b>executes sentence</b>, does not judge", "<b>Muhammad Reza Khan</b> (Naib Nazim) held CJ of both SDA and SNA", w=34),
  tb(["Level", "Civil (Diwani)", "Criminal (Nizamat)"], ["Suba", "SDA, CJ Diwan (Reza Khan held both)", "SNA, headed by Naib Nazim"], ["District", "Diwani Adalat: Pandits (Hindu), Maulvis (Muslim); revenue: Amil (Amalguzar)", "Nizamat/Faujdari Adalat: Kazi judges, Mufti interprets, Faujdar executes"], ["Local", "Zamindar's Kachari: LR + non-personal", "Zamindar: petty only"], ["Law", "Personal law (Hindu law, Muslim law)", "Islamic law for all"]),
  bx('pk', "<b>Teacher:</b> civil courts <b>religion-specific</b> (judge by faith); criminal courts <b>State-uniform</b> (ruling State's law for all). Remember the pair: standard books stop at personal law (civil) and criminal law (criminal): <b>Civil = Hindu law for Hindus, Muslim law for Muslims; Criminal = Islamic law for everyone.</b>"),
  bx('ye', "<b>CJ of SNA:</b> general Mughal board SNA CJ = Nazim/Subadar; 18th-century Bengal boards + handout = <b>Naib Nazim</b> (Subadar distant; Reza Khan ran courts, EIC's Diwan since 1765). Use Naib Nazim for SNA, Diwan for SDA. <b>Amil vs Amalguzar:</b> handout uses Amil for 18th-century Bengal; canonical Mughal term Amalguzar (district revenue officer): same post."),
  t("<b>Dual Government 1765-72</b>", "After ToA 1765 EIC got <b>Diwani</b>: revenue administration, Treasury, property / civil courts (not health, education: private or religious patronage)", "<b>Nawab kept Nizamat</b> (law and order) = <b>Dual Government</b>; <b>Orientalism</b>: no rush to impose own system", "<b>Reza Khan headed both</b> Diwani (for EIC) and Nizamat (for Nawab); Indian officials effective decision-makers; EIC wanted LR", "<b>Outcome:</b> poor revenue; law and order fell; <b>GBF 1770 killed about one-third of Bengal</b> ('Poverty leads to Crimes')", w=24),
  t("<b>1772 Direct Government (Hastings 73-85)</b>", "<b>Hastings 73-85</b> (Governor from 1772, <b>GG of Bengal 1773-1785</b>) <b>ended Dual Government</b>: direct Diwani + Nizamat; rule of law, equality before law; Orientalism shifts to <b>hybrid</b>", "<b>Reza Khan imprisoned without trial 1772-74</b> (corruption, poor law and order); <b>released 1774, reinstated head of SNA</b>", w=22),
  tb(["Court (1772)", "Judge", "Detail"], ["Diwani (civil), district", "British <b>DC</b>, assisted by Pandits + Maulvis", "Personal laws in marriage, inheritance"], ["Nizamat (criminal), district", "<b>Kazis + Muftis continue</b>, supervised by European DC", "Law and order too sensitive to replace (board: 'L and O = sensitive, therefore continue with K and M as J')"], ["SDA + SNA", "Governor (from 1773 GG of Bengal) + Council members", "Top of both ladders passes to Company"]),
