  sec("CORNWALLIS 86-93 CODE OF 1793 (judiciary)", 'r'),
  t("<b>Why he reformed</b>", "<b>Cornwallis 86-93</b> (GG 1786-1793): most systematic early judicial reform; just did <b>PS 1793</b>: new big Zamindars as private owners needed <b>secure property rights</b>: trusted courts, revenue officials who cannot harass; tax collector must not judge the appeal against himself", "<b>Separation of Powers at DC level:</b> DC stripped of <b>all judicial powers</b>, only revenue + administration", "Board 'Imagine': DC applies <b>Sunset Clause</b>, Zamindar files case; if judge = same DC, conflict of interest; <b>Cornwallis 86-93 = AUTHORITARIAN</b>, hence removed Indians from all senior positions (other side of same reform)", w=26),
  bx('pk', "<b>Prelims 2010 (c)</b> " + P('2010') + ": DC deprived of judicial powers because <b>absolute power in one person was undesirable</b> (separation of powers; post-PS Zamindar class needed independent courts). (a) revenue efficiency = partial truth (b) 'judicial = European only, revenue can be Indian' wrong: he removed Indians from <b>all</b> senior posts incl. revenue (d) 'judicial work needed deep India knowledge' = partial truth. Trigger = conflict of interest after PS 1793."),
  t("<b>Civil side</b>", "18 Mofussil courts replaced by <b>district Diwani Adalats</b> + <b>City Courts</b> (urban)", "<b>Bengal in 4 divisions: Patna, Murshidabad, Calcutta, Dacca</b>, each with a <b>Provincial Court of Appeal</b>", "Appeals: district / City > <b>Provincial Court of Appeal</b> > <b>SDA shifted Murshidabad to Calcutta</b>", "Personal laws continued; <b>PS 1793</b> governed LR disputes; per <b>Charter Act 1793</b> regulations codified, written orders compulsory, laws printed in vernaculars", w=24),
  bx('bl', "<b>Code 1781 vs Code 1793 = issuing authority:</b> 1781 by GG (Bengal) can be changed by a later GG; 1793 via Charter Act 1793, 'By Br (P)' (British Parliament) = more weight."),
  t("<b>Criminal side</b>", "Faujdari / Nizamat Adalats at district <b>abolished</b>; <b>4 Provincial Courts of Circuit</b> in the four divisions (<b>Court of Circuit</b> = travelling bench, rotating districts: week 1 district 1... so no district needs own criminal court)", "Appeals to <b>SNA</b>", "<b>Islamic law continued with British modifications</b> = <b>Anglo-Muhammadan law</b>, applied about <b>70 years until IPC 1860</b>", w=22),
  tb(["Anglo-Muhammadan example (handout only)", "Islamic law (strict Hanafi)", "Cornwallis 86-93 change"], ["A weapon rule to intent rule", "Capital murder depended on weapon (sharp iron = murder; strangling, drowning, heavy stone often lesser)", "<b>Intent decides</b>, not instrument (mens rea)"], ["B end of blood money (Diyat)", "Murder largely private: heirs could pardon for compensation", "Relatives cannot pardon: major crime = offence against <b>State</b>"], ["C abolition of mutilation", "Serious theft / dacoity = amputation of hand or foot", "Outlawed; <b>hard labour, rigorous imprisonment 7 to 14 years</b>"]),
  t("<b>Personnel + lawyers</b>", "Authoritarian: <b>Indians removed from all senior posts</b>; all courts headed by Europeans; Kazis + Muftis only <b>assistants</b>; <b>Naib Nazim office abolished</b> (board '[NA ABOLISHED]')", "<b>Progressive: lawyers permitted</b> = new class of Indian lawyers; with PS (land a tradeable commodity) also <b>property dealers</b>; board: <b>Cornwallis 86-93, father of: CS (civil services), property dealers, lawyer</b>", w=22),
  tb(["Why litigation rose (class slide)", "What happened"], ["1 Separation of Powers (key)", "DC lost judicial + magisterial powers: disputes once swift and on the spot now formally filed in Diwani Adalats"], ["2 Court fees abolished", "'Accessible' justice flooded courts with genuine + frivolous suits; <b>reimposed 1795</b> (2 years later)"], ["3 Legal profession", "Vakils recognised + rigid appeals: cases deliberately prolonged"]),
