  tb(["Barrier (eligibility on paper, not access)", "Detail"], ["Age limit", "Max <b>18 to 23</b>, deliberately low. <b>1859</b> Crown cut max age to <b>23</b>; <b>22 in 1860</b>; <b>21 in 1866</b>; <b>19 in 1876</b> (implemented 1878, not to hit those preparing). Board: 'not imp' (do not memorise every step)"], ["Syllabus", "<b>English Literature</b> = source of values, to make what <b>Macaulay</b> called <b>'Brown Sahibs'</b> (Indians English in culture + values, loyal to Britain)"], ["Venue", "<b>Only London</b>"], ["Indian candidate", "Travel cost; inferior preparation; syllabus rewarded English culture knowledge"], ["First Indians", "<b>1864 Satyendranath Tagore</b> (brother of Rabindranath) first Indian to clear CCS exam; <b>1867 four more</b>"]),
